testsCode:
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { comTimeout } from './solution.mjs';

function depois(ms, valor) {
  return new Promise((resolve) => setTimeout(resolve, ms, valor));
}

test('devolve o valor quando a promessa resolve antes do limite', async () => {
  assert.equal(await comTimeout(depois(3, 'pronto'), 10), 'pronto');
});

test('rejeita com tempo esgotado quando a promessa demora demais', async () => {
  await assert.rejects(() => comTimeout(depois(10, 'tarde'), 3), /tempo esgotado/);
});

test('rejeita quando limiteMs é inválido', async () => {
  await assert.rejects(() => comTimeout(depois(2, 'x'), 0), /maior que zero/);
});

solutionCode:
export function comTimeout(promessa, limiteMs) {
  if (typeof limiteMs !== 'number' || limiteMs < 1) {
    return Promise.reject(new Error('limiteMs deve ser maior que zero'));
  }
  return Promise.race([
    promessa,
    new Promise((_, rejeitar) => {
      setTimeout(() => rejeitar(new Error('tempo esgotado: ' + limiteMs + 'ms')), limiteMs);
    }),
  ]);
}
